                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  printf("? ");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      scanf("%d", &numero);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
